        }),
        status: "in_progress",
        priority: "urgent",
        labelIds: [label.id],
      },
      north.userIds.owner,
      number,
    );

    // A near-identical issue that only differs by status must not match.
    const otherNumber = await issueRepo.nextIssueNumber(north.org.id, north.project.id);
